<?php
namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller; use App\Models\Expense; use App\Models\Property; use App\Models\PropertySpace; use App\Models\Vendor; use App\Services\AuditService; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class ExpenseController extends Controller { public function vendors(Request $r):JsonResponse{return $this->success(['items'=>Vendor::where('organization_id',$r->attributes->get('organization_id'))->when($r->filled('status'),fn($q)=>$q->where('status',$r->string('status')))->orderBy('name')->get()->map(fn($v)=>$this->vendorData($v))]);} public function storeVendor(Request $r):JsonResponse{$d=$r->validate(['code'=>['required','string','max:50'],'name'=>['required','string','max:200'],'mobile'=>['nullable','string','max:30'],'email'=>['nullable','email'],'taxNumber'=>['nullable','string','max:80']]);$org=$r->attributes->get('organization_id');$v=Vendor::create(['id'=>(string)Str::uuid(),'organization_id'=>$org,'code'=>$d['code'],'name'=>$d['name'],'mobile'=>$d['mobile']??null,'email'=>$d['email']??null,'tax_number'=>$d['taxNumber']??null]);AuditService::record($org,$r->user()->id,'vendor.created','vendor',$v->id,null,$this->vendorData($v));return $this->success($this->vendorData($v),[],201);} public function index(Request $r):JsonResponse{$items=Expense::where('organization_id',$r->attributes->get('organization_id'))->when($r->filled('propertyId'),fn($q)=>$q->where('property_id',$r->string('propertyId')))->when($r->filled('approvalStatus'),fn($q)=>$q->where('approval_status',$r->string('approvalStatus')))->orderByDesc('expense_date')->get()->map(fn($e)=>$this->data($e));return $this->success(['items'=>$items]);} public function show(Request $r,string $id):JsonResponse{return $this->success($this->data($this->find($r,$id)));} public function store(Request $r):JsonResponse{$d=$this->validateExpense($r,true);$org=$r->attributes->get('organization_id');$e=DB::transaction(function()use($d,$org){$p=Property::where('organization_id',$org)->findOrFail($d['propertyId']);if(($d['spaceId']??null)&&!PropertySpace::where('organization_id',$org)->where('property_id',$p->id)->whereKey($d['spaceId'])->exists())abort(422,'المساحة لا تتبع العقار.');$gross=round((float)$d['netAmount']+(float)($d['vatAmount']??0),2);if(isset($d['grossAmount'])&&round((float)$d['grossAmount'],2)!==$gross)abort(422,'إجمالي المصروف لا يطابق الصافي والضريبة.');return Expense::create(['id'=>(string)Str::uuid(),'organization_id'=>$org,'property_id'=>$p->id,'space_id'=>$d['spaceId']??null,'owner_id'=>$d['ownerId']??null,'vendor_id'=>$d['vendorId']??null,'vendor_name'=>$d['vendorName']??null,'description'=>$d['description'],'category'=>$d['category'],'net_amount'=>$d['netAmount'],'vat_amount'=>$d['vatAmount']??0,'gross_amount'=>$gross,'expense_date'=>$d['expenseDate'],'invoice_number'=>$d['invoiceNumber']??null,'chargeable_to_owner'=>$d['chargeableToOwner']??false,'approval_status'=>($d['requiresApproval']??false)?'pending':'not_required','status'=>'draft']);});AuditService::record($org,$r->user()->id,'expense.created','expense',$e->id,null,$this->data($e));return $this->success($this->data($e),[],201);} public function decide(Request $r,string $id):JsonResponse{$d=$r->validate(['decision'=>['required','in:approved,rejected'],'reason'=>['nullable','string','max:1000']]);$org=$r->attributes->get('organization_id');$e=DB::transaction(function()use($r,$id,$d,$org){$e=$this->find($r,$id,true);if($e->approval_status!=='pending')abort(409,'المصروف ليس بانتظار الاعتماد.');$before=$this->data($e);$e->update(['approval_status'=>$d['decision'],'status'=>$d['decision']==='approved'?'confirmed':'cancelled','version'=>$e->version+1]);DB::table('expense_approvals')->insert(['id'=>(string)Str::uuid(),'expense_id'=>$e->id,'decision'=>$d['decision'],'decided_by'=>$r->user()->id,'reason'=>$d['reason']??null,'decided_at'=>now()]);AuditService::record($org,$r->user()->id,'expense.'.$d['decision'],'expense',$e->id,$before,$this->data($e),$d['reason']??null);return $e;});return $this->success($this->data($e));} private function validateExpense(Request $r,bool $create):array{return $r->validate(['propertyId'=>[$create?'required':'sometimes','uuid'],'spaceId'=>['nullable','uuid'],'ownerId'=>['nullable','uuid'],'vendorId'=>['nullable','uuid'],'vendorName'=>['nullable','string','max:200'],'description'=>[$create?'required':'sometimes','string','max:5000'],'category'=>[$create?'required':'sometimes','string','max:80'],'netAmount'=>[$create?'required':'sometimes','numeric','gte:0'],'vatAmount'=>['nullable','numeric','gte:0'],'grossAmount'=>['nullable','numeric','gte:0'],'expenseDate'=>[$create?'required':'sometimes','date'],'invoiceNumber'=>['nullable','string','max:100'],'chargeableToOwner'=>['boolean'],'requiresApproval'=>['boolean']]);} private function find(Request $r,string $id,bool $lock=false):Expense{$q=Expense::where('organization_id',$r->attributes->get('organization_id'));if($lock)$q->lockForUpdate();return $q->findOrFail($id);} private function vendorData(Vendor $v):array{return ['id'=>$v->id,'code'=>$v->code,'name'=>$v->name,'mobile'=>$v->mobile,'email'=>$v->email,'taxNumber'=>$v->tax_number,'status'=>$v->status];} private function data(Expense $e):array{return ['id'=>$e->id,'propertyId'=>$e->property_id,'spaceId'=>$e->space_id,'ownerId'=>$e->owner_id,'vendorId'=>$e->vendor_id,'vendorName'=>$e->vendor_name,'description'=>$e->description,'category'=>$e->category,'netAmount'=>(float)$e->net_amount,'vatAmount'=>(float)$e->vat_amount,'grossAmount'=>(float)$e->gross_amount,'expenseDate'=>$e->expense_date,'invoiceNumber'=>$e->invoice_number,'chargeableToOwner'=>$e->chargeable_to_owner,'approvalStatus'=>$e->approval_status,'status'=>$e->status,'version'=>$e->version];}}
